NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Titus'

CHAPTERS = {
    1: {
        1: 'Paavali, Jumalan palvelija ja Jeesuksen Kristuksen apostoli Jumalan valittujen uskoa ja jumalanpelon mukaista totuuden tuntemista varten,',
        2: 'sen iankaikkisen elämän toivon perusteella, jonka Jumala, joka ei valehtele, on luvannut ennen ikuisia aikoja.',
        3: 'Mutta hän ilmoitti sanansa omalla ajallaan saarnassa, joka uskottiin minulle Jumalan, meidän vapahtajamme käskyn mukaan:',
        4: 'Tiitukselle, oikealle pojalleni yhteisen uskomme mukaan. Armo ja rauha Isältä Jumalalta ja Vapahtajaltamme Kristukselta Jeesukselta!',
        5: 'Minä jätin sinut Kreetalle sitä varten, että järjestäisit, mitä vielä jäi järjestämättä, ja että asettaisit, niin kuin minä sinulle määräsin, joka kaupunkiin vanhimmat,',
        6: 'jos olisi joku nuhteeton, yhden vaimon mies, jonka lapset ovat uskovia, eivät irstaudesta syytettyjä eivätkä niskoittelevia.',
        7: 'Sillä kaitsijan on, niin kuin Jumalan huoneenhaltijan tulee, oltava nuhteeton, ei itserakas, ei äkkipikainen, ei juomari, ei riitelijä, ei häpeällisen voiton pyytäjä,',
        8: 'vaan vieraanvarainen, hyvää rakastava, maltillinen, vanhurskas, pyhä, itsensä hillitsevä.',
        9: 'Hänen tulee pysyä kiinni opinmukaisessa, luotettavassa sanassa, että olisi kykenevä sekä lohduttamaan terveellä opilla että nuhtelemaan vastaansanojia.',
        10: 'Sillä paljon on niskoittelevia, turhanpuhujia ja eksyttäjiä, varsinkin ympärileikatuista.',
        11: 'Sellaisilta on suu tukittava, sillä he kääntävät ylösalaisin kokonaisia huonekuntia opettamalla sopimattomia häpeällisen voiton vuoksi.',
        12: 'Eräs heistä, heidän oma profeettansa, on sanonut: "Petturi Kreetan mies, peto ilkeä, ahmatti laiska."',
        13: 'Tämä todistus on tosi. Sen tähden nuhtele heitä ankarasti, että tulisivat uskossa terveiksi',
        14: 'eivätkä kiinnittäisi huomiotaan juutalaisiin taruihin eivätkä totuudesta pois kääntyvien ihmisten käskyihin.',
        15: 'Kaikki on puhdasta puhtaille, mutta saastaisille ja uskottomille mikään ei ole puhdasta, vaan heidän sekä mielensä että omatuntonsa on saastainen.',
        16: 'He väittävät tuntevansa Jumalan, mutta kieltävät hänet teoillaan, sillä he ovat inhottavia, tottelemattomia ja kaikkiin hyviin tekoihin kelvottomia.',
    },
    2: {
        1: 'Mutta puhu sinä sitä, mikä sopii terveeseen oppiin.',
        2: 'Vanhat miehet olkoot raittiita, arvokkaita, hurskaita ja uskossa, rakkaudessa ja kärsivällisyydessä terveitä.',
        3: 'Samoin vanhat naiset olkoot käytöksessään kuten pyhien sopii, ei panettelijoita, ei paljon viinin orjia, vaan hyvään opettajia,',
        4: 'voidakseen neuvoa nuoria naisia rakastamaan miehiään ja lapsiaan,',
        5: 'olemaan itsensä hillitseviä, puhtaita, hyviä kotinsa hoitajia, alamaisia omille miehilleen, ettei Jumalan sana tulisi pilkatuksi.',
        6: 'Nuorempia miehiä kehota samoin käyttäytymään itsensä hilliten.',
        7: 'Aseta itsesi kaikessa hyvien tekojen esikuvaksi, puhtaassa opissa, arvokkuudessa ja turmeltumattomuudessa.',
        8: 'Olkoon puheesi tervettä ja moitteetonta, että vastustaja häpeäisi, kun hänellä ei ole mitään pahaa sanottavana meistä.',
        9: 'Kehota palvelijoita olemaan isännilleen kaikessa alamaisia, heille mieliksi, etteivät vastustele,',
        10: 'etteivät näpistele, vaan kaikin tavoin osoittavat rehtiä uskollisuutta, että he kaunistaisivat kaikessa Jumalan, meidän vapahtajamme, opin.',
        11: 'Sillä Jumalan pelastava armo on ilmestynyt kaikille ihmisille',
        12: 'ja kasvattaa meitä, jotta hyläten jumalattomuuden ja maailmalliset himot eläisimme itsemme hilliten vanhurskaasti ja jumalanpelossa nykyisessä maailmanajassa,',
        13: 'odottaessamme autuaan toivon täyttymistä ja suuren Jumalamme ja Vapahtajamme Kristuksen Jeesuksen kirkkauden ilmestymistä,',
        14: 'hänen, joka antoi itsensä edestämme lunastaakseen meidät kaikesta laittomuudesta ja puhdistaakseen itselleen omaisuudeksi kansan, joka tekee ahkerasti hyviä tekoja.',
        15: 'Puhu tätä, kehota ja nuhtele kaikella käskyvallalla. Älköön kukaan halveksiko sinua.',
    },
    3: {
        1: 'Muistuta heitä olemaan hallituksille ja esivalloille alamaisia ja kuuliaisia sekä kaikkiin hyviin tekoihin valmiita,',
        2: 'etteivät ketään herjaa, eivät riitele, vaan ovat lempeitä ja osoittavat kaikkea sävyisyyttä kaikkia ihmisiä kohtaan.',
        3: 'Olimmehan mekin ennen ymmärtämättömiä, tottelemattomia, eksyksissä, monien himojen ja nautintojen orjia, elimme pahuudessa ja kateudessa, olimme inhottavia ja vihasimme toisiamme.',
        4: 'Mutta kun Jumalan, meidän vapahtajamme, hyvyys ja ihmisrakkaus ilmestyi,',
        5: 'hän pelasti meidät, ei vanhurskaudessa tekemiemme tekojen ansiosta, vaan laupeutensa mukaan uudestisyntymisen pesun ja Pyhän Hengen uudistuksen kautta.',
        6: 'Tämän Hengen hän runsaasti vuodatti meihin Vapahtajamme Jeesuksen Kristuksen kautta,',
        7: 'että me vanhurskaiksi julistettuina hänen armonsa kautta tulisimme iankaikkisen elämän perillisiksi toivon mukaan.',
        8: 'Tämä sana on varma, ja tahdon, että sinä näitä teroitat lujasti mieliin, niin että ne, jotka ovat Jumalaan uskoneet, harjoittaisivat ahkerasti hyviä tekoja. Ne ovat hyviä ja hyödyllisiä ihmisille.',
        9: 'Mutta vältä typeriä riitakysymyksiä ja sukuluetteloita sekä kinastelua ja kiistoja laista, sillä ne ovat hyödyttömiä ja turhia.',
        10: 'Harhaoppista ihmistä karta, varoitettuasi häntä kerran tai kahdesti,',
        11: 'sillä tiedät, että sellainen ihminen on joutunut harhaan ja tekee syntiä itse itsensä tuominneena.',
        12: 'Kun lähetän luoksesi Artemaan tai Tykikoksen, tule viipymättä luokseni Nikopoliin, sillä olen päättänyt viettää talven siellä.',
        13: 'Varusta huolellisesti matkalle Zeenas, lainoppinut, ja Apollos, ettei heiltä puuttuisi mitään.',
        14: 'Oppikoot meikäläisetkin tarpeen vaatiessa harjoittamaan hyviä tekoja, etteivät olisi hedelmättömiä.',
        15: 'Tervehdyksen lähettävät sinulle kaikki, jotka ovat kanssani. Sano tervehdys niille, jotka pitävät meitä rakkaina uskossa. Armo olkoon teidän kaikkien kanssa. Aamen.',
    },
}
